#include <iostream>
#include <string>

struct MyObject {
  std::string data;
  MyObject(const std::string& d) : data(d) { std::cout << "MyObject constructor called\n"; }
  MyObject(const MyObject& other) : data(other.data) { std::cout << "MyObject copy constructor called\n"; }
  ~MyObject() { std::cout << "MyObject destructor called\n"; }
};

MyObject createObject(const std::string& str) {
  MyObject obj(str); // NRVO likely here
  return obj;       
}

MyObject createObject2(const std::string& str) {
  MyObject obj(str);
  MyObject temp = obj; // Prevents NRVO
  return temp;
}

int main() {
  MyObject myObj1 = createObject("Hello");
  MyObject myObj2 = createObject2("World");
  return 0;
}
